from fastapi import FastAPI
import pytest

app = FastAPI()

@app.vibe("/vibe")
def vibe_route():
    return {"message": "vibe check passed"}

def test_vibe_route():
    from fastapi.testclient import TestClient
    client = TestClient(app)
    # Since VIBE is not a standard HTTP method, we need to see if TestClient/Starlette supports it.
    # Starlette's TestClient uses httpx.
    # We can try to make a request with method="VIBE".
    response = client.request("VIBE", "/vibe")
    assert response.status_code == 200
    assert response.json() == {"message": "vibe check passed"}

if __name__ == "__main__":
    try:
        test_vibe_route()
        print("Success!")
    except Exception as e:
        print(f"Failure: {e}")
        import traceback
        traceback.print_exc()
        exit(1)
